1: import type { SimulationEvent } from '../contracts/events';
2: import type { MatchDTO, MatchSettings, PlayerHoleScore, PlayerProfile } from '../contracts/game';
3: import type { Course, Hole } from '../courses/types';
4: import { GameplayStateMachine } from './StateMachine';
5: import { ScoreManager } from './ScoreManager';
6: import { TurnManager } from './TurnManager';
7: 
8: export class MatchManager {
9:   private readonly scores = new ScoreManager();
10:   private readonly turns = new TurnManager();
11:   private machine = new GameplayStateMachine('lobby');
12: 
13:   createMatch(id: string, settings: MatchSettings, players: readonly PlayerProfile[]): MatchDTO {
14:     if (players.length < 1 || players.length > settings.maxPlayers) throw new Error('Invalid player count');
15:     this.machine = new GameplayStateMachine('lobby');
16:     return {
17:       id,
18:       phase: 'lobby',
19:       settings,
20:       players: players.map(player => ({ ...player, connected: true, totalStrokes: 0, holeScores: [] })),
21:       currentHoleIndex: 0,
22:     };
23:   }
24: 
25:   startMatch(match: MatchDTO, course: Course, now = Date.now()): MatchDTO {
26:     if (course.id !== match.settings.courseId) throw new Error('Course does not match match settings');
27:     const firstHole = course.holes[0];
28:     if (!firstHole) throw new Error('Course has no holes');
29:     this.machine = new GameplayStateMachine(match.phase);
30:     this.machine.transition('hole-intro');
31:     return this.prepareHole({ ...match, phase: this.machine.phase, startedAt: now }, firstHole);
32:   }
33: 
34:   beginAiming(match: MatchDTO, hole: Hole): MatchDTO {
35:     this.sync(match.phase);
36:     this.machine.transition('aiming');
37:     return { ...match, phase: this.machine.phase, activePlayerId: this.turns.firstEligiblePlayer(match, hole.id) };
38:   }
39: 
40:   markShotSubmitted(match: MatchDTO): MatchDTO {
41:     this.sync(match.phase);
42:     this.machine.transition('simulating');
43:     return { ...match, phase: this.machine.phase };
44:   }
45: 
46:   applySimulationEvent(match: MatchDTO, course: Course, event: SimulationEvent, now = Date.now()): MatchDTO {
47:     const hole = course.holes[match.currentHoleIndex];
48:     if (!hole) throw new Error('Current hole does not exist');
49: 
50:     if (event.type === 'shot-accepted') {
51:       return this.updateScore(match, event.command.playerId, hole.id, score => this.scores.recordStroke(score));
52:     }
53:     if (event.type === 'ball-reset') {
54:       return this.updateScore(match, event.playerId, hole.id, score => this.scores.addPenalty(score, event.penaltyStrokes));
55:     }
56:     if (event.type === 'ball-holed') {
57:       const completed = this.updateScore(match, event.playerId, hole.id, score => this.scores.complete(score, now - (match.startedAt ?? now)));
58:       return this.advanceAfterFinish(completed, course, hole.id, event.playerId, now);
59:     }
60:     if (event.type === 'ball-stopped') {
61:       return this.advanceTurn(match, course, hole.id, event.playerId, now);
62:     }
63:     return match;
64:   }
65: 
66:   enforceStrokeLimit(match: MatchDTO, course: Course, playerId: string, now = Date.now()): MatchDTO {
67:     const hole = course.holes[match.currentHoleIndex];
68:     if (!hole) throw new Error('Current hole does not exist');
69:     const updated = this.updateScore(match, playerId, hole.id, score => this.scores.applyStrokeLimit(score, match.settings.strokeLimitPerHole));
70:     const score = this.findScore(updated, playerId, hole.id);
71:     return score.completed ? this.advanceAfterFinish(updated, course, hole.id, playerId, now) : updated;
72:   }
73: 
74:   pause(match: MatchDTO): MatchDTO {
75:     this.sync(match.phase);
76:     this.machine.pause();
77:     return { ...match, phase: this.machine.phase };
78:   }
79: 
80:   resume(match: MatchDTO): MatchDTO {
81:     const phase = this.machine.resume();
82:     return { ...match, phase };
83:   }
84: 
85:   private prepareHole(match: MatchDTO, hole: Hole): MatchDTO {
86:     const players = match.players.map(player => player.holeScores.some(score => score.holeId === hole.id)
87:       ? player
88:       : { ...player, holeScores: [...player.holeScores, this.scores.createHoleScore(player.id, hole.id)] });
89:     return { ...match, players, activePlayerId: undefined };
90:   }
91: 
92:   private advanceAfterFinish(match: MatchDTO, course: Course, holeId: string, playerId: string, now: number): MatchDTO {
93:     if (this.turns.allPlayersFinishedHole(match, holeId)) return this.finishHole(match, course, now);
94:     return this.advanceTurn(match, course, holeId, playerId, now);
95:   }
96: 
97:   private advanceTurn(match: MatchDTO, course: Course, holeId: string, currentPlayerId: string, now: number): MatchDTO {
98:     if (this.turns.allPlayersFinishedHole(match, holeId)) return this.finishHole(match, course, now);
99:     this.sync(match.phase);
100:     if (this.machine.phase === 'simulating') this.machine.transition('aiming');
101:     return { ...match, phase: this.machine.phase, activePlayerId: this.turns.nextEligiblePlayer(match, holeId, currentPlayerId) };
102:   }
103: 
104:   private finishHole(match: MatchDTO, course: Course, now: number): MatchDTO {
105:     this.sync(match.phase);
106:     if (this.machine.phase === 'simulating' || this.machine.phase === 'aiming') this.machine.transition('hole-results');
107:     if (match.currentHoleIndex >= course.holes.length - 1) {
108:       this.machine.transition('match-results');
109:       return {
110:         ...match,
111:         phase: this.machine.phase,
112:         activePlayerId: undefined,
113:         finishedAt: now,
114:         players: match.players.map(player => ({ ...player, totalStrokes: this.scores.totalForPlayer(player) })),
115:       };
116:     }
117:     this.machine.transition('hole-intro');
118:     const nextIndex = match.currentHoleIndex + 1;
119:     const nextHole = course.holes[nextIndex];
120:     if (!nextHole) throw new Error('Next hole does not exist');
121:     return this.prepareHole({ ...match, phase: this.machine.phase, currentHoleIndex: nextIndex }, nextHole);
122:   }
123: 
124:   private updateScore(match: MatchDTO, playerId: string, holeId: string, updater: (score: PlayerHoleScore) => PlayerHoleScore): MatchDTO {
125:     return {
126:       ...match,
127:       players: match.players.map(player => {
128:         if (player.id !== playerId) return player;
129:         const holeScores = player.holeScores.map(score => score.holeId === holeId ? updater(score) : score);
130:         return { ...player, holeScores, totalStrokes: holeScores.reduce((sum, score) => sum + score.strokes, 0) };
131:       }),
132:     };
133:   }
134: 
135:   private findScore(match: MatchDTO, playerId: string, holeId: string): PlayerHoleScore {
136:     const score = match.players.find(player => player.id === playerId)?.holeScores.find(entry => entry.holeId === holeId);
137:     if (!score) throw new Error(`Missing score for player ${playerId} on hole ${holeId}`);
138:     return score;
139:   }
140: 
141:   private sync(phase: MatchDTO['phase']): void {
142:     if (this.machine.phase !== phase) this.machine = new GameplayStateMachine(phase);
143:   }
144: }
